-- 2) Uplift 640 (notes append: replay once)
UPDATE scholarships SET coverage_type = 'Tuition Subsidy + Stipend', deadline = 'No separate scholarship deadline: you apply inside the NTU degree application by ticking the scholarship box, so the binding dates are the NTU international degree application rounds (the September-entry first round opened 29 September 2026). See the degree-students application page for each round''s closing date.', degree_levels = '["Bachelor''s"]', min_gpa = NULL, min_ielts = NULL, description = 'National Taiwan University offers this scholarship to international undergraduate degree applicants who ask for it inside the admission application: a tuition subsidy of up to TWD 100,000 each semester - the university prints about USD 3,333, explicitly as a rough estimate - plus a monthly stipend of TWD 8,000, for the designated years of study of the programme. The application is a single checkbox in the degree online application system, with no extra documents or separate procedure. Taiwan Scholarship awardees are told not to apply for NTU scholarships at the same time. The university publishes separate variants for Central and Eastern European countries and for the British Virgin Islands (same amounts, up to four years), while the Taiwanese government and individual colleges run their own schemes alongside; graduate students are served by different NTU awards, such as the in-study International Outstanding Graduate Student Scholarship catalogued separately.', requirements = REPLACE(requirements, 'keeping a GPA of 3.38 or above.', 'keeping a GPA of 3.38 or above on NTU''s grading scale (a continuation standard, not an entry cut-off; no scholarship-level GPA or English-test threshold is published for entry).'), funding_type = 'University admission-stage scholarship (checkbox in the degree application): tuition subsidy up to TWD 100,000 per semester plus TWD 8,000 monthly stipend', tuition_coverage = 'Tuition subsidy of up to TWD 100,000 per semester for the designated years of study, renewed annually at a GPA of 3.38 or above; deferring admission forfeits eligibility. The subsidy excludes administrative fees, thesis-advisor fees, insurance, accommodation, internet service and credit fees, which the student pays - so it is a substantial contribution, not a guaranteed full ride where programme tuition exceeds the cap.', accommodation = NULL, english_requirements = 'No scholarship-level English score is published: NTU sets no IELTS (or other test) threshold for this award itself; language requirements are those of the admitted undergraduate programme (English- or Chinese-taught).', required_documents = '["NTU degree application with the scholarship application box ticked - no separate scholarship documents or procedure"]', rounds = '[{"pattern":"Rides on the NTU international degree application rounds; the September-entry first round opened 29 September 2026. Tick the scholarship box inside the degree application - there is no separate scholarship deadline."}]', expected_opening_period = 'With each NTU degree application round (September-entry first round opened 29 September 2026)', expected_deadline_period = 'The closing date of the degree application round you apply in', application_status = 'open', last_verified_at = '2026-10-29 17:00:00+05', last_updated_at = '2026-10-29 17:00:00+05', source_reliability = 10, notes = notes || ' Enrichment Batch 33 (2026-10-29) uplift from rel 8 to rel 10, re-verified first-hand against the NTU admissions scholarships page (source 3149, read 2026-10-29): degree levels corrected to undergraduate only (this is the Undergraduate Student Scholarship; the graduate in-study award is record 342); importer minima min_gpa 3.6 / min_ielts 6.5 and the IELTS requirement text removed (no entry threshold is published; the page''s 3.38 is the annual renewal standard and stays textual); award normalised to NULL/TWD/month/variable (the stored TWD 100,000 ''fixed''/''year'' amount contradicted the per-semester cap - amounts now prose-only); required_documents reduced to the single checkbox step the page describes; status set to open on the OIA-announced September-entry first round (opened 29 September 2026); empty-string accommodation cleared; side-table row us 62, which still carried the pre-correction ''50-80% Dicount'' text, rewritten. Caveat: NTU''s current-students ISSS page administers an ''NTU Scholarship for International Degree Student'' under a variant name with an NTD 65,000 waiver cap; this record follows the applicant-facing admissions page - confirm the cap applied to your cohort at admission.', award_amount = NULL, award_currency = 'TWD', award_period = 'month', award_basis = 'variable' WHERE id = 640;

